211	/**
212	 * Computes the prerequisite pipeline type for `pipelineType` given the WP's
213	 * active_pipeline_stages. The canonical ordering filters the active set, and the
214	 * immediately preceding active stage is the prerequisite.
215	 * Returns null when `pipelineType` is the first active stage or is not active.
216	 *
217	 * When activeStages is omitted, defaults to DEFAULT_PIPELINE_STAGES (legacy 4-stage).
218	 */
219	export function resolvePrerequisite(
220	  pipelineType: PipelineType,
